// --- Relocation Entry (Input to Linker) ---
struct Relocation {
    uint64_t offset;    // Location in section needing adjustment (P)
    uint32_t symbol_idx; // Symbol table index (S)
    uint8_t  type;      // Type of adjustment (e.g., PC-relative)
    int64_t  addend;    // Constant offset (A)
};

// --- Linker Address Patching Logic ---
uint64_t resolve_address(
    struct Relocation R, uint64_t SymAddr, uint64_t PatchLoc)
{
    // Common Relocation Types:
    if (R.type == R_ABS64) {
        // Absolute: Value = S + A
        return SymAddr + R.addend;
    }
    if (R.type == R_PC32) {
        // PC-Relative: Value = (S + A) - P
        return (SymAddr + R.addend) - PatchLoc;
    }
    return 0; // Unhandled type
}
